// Minimal independent JSON-RPC bridge for the documented PeerTube embed methods.
function createPeerBridge(frame){const origin=new URL(frame.src).origin,pending=new Map();let sequence=1,closed=false,readyResolve,readyReject;const ready=new Promise((resolve,reject)=>{readyResolve=resolve;readyReject=reject});const deadline=setTimeout(()=>readyReject(Error('PeerTube не ответил')),12000);
 const send=value=>frame.contentWindow?.postMessage(JSON.stringify(value),origin);
 const call=(method,params)=>new Promise((resolve,reject)=>{if(closed){reject(Error('Player closed'));return}const id=sequence++,timer=setTimeout(()=>{pending.delete(id);reject(Error('Player response timeout'))},4000);pending.set(id,{resolve,reject,timer});send({id,method:'peertube::'+method,params})});
 const received=e=>{if(e.source!==frame.contentWindow||e.origin!==origin)return;let d;try{d=typeof e.data==='string'?JSON.parse(e.data):e.data}catch{return}if(!d||typeof d!=='object')return;
  if(d.method==='peertube::__ready'){if(d.params==='ping')send({method:d.method,params:'pong'});else if(d.params?.type==='publish-request')send({method:d.method,params:{type:'publish-reply',publish:[]}});call('isReady').then(value=>{if(value){clearTimeout(deadline);readyResolve()}}).catch(()=>{});return}
  if(d.method==='peertube::ready'){clearTimeout(deadline);readyResolve();if(d.id!==undefined)send({id:d.id,result:true});return}
  const p=pending.get(d.id);if(p){pending.delete(d.id);clearTimeout(p.timer);d.error?p.reject(Error(String(d.error))):p.resolve(d.result)}
 };window.addEventListener('message',received);
 return {ready,call,destroy(){closed=true;clearTimeout(deadline);window.removeEventListener('message',received);for(const p of pending.values()){clearTimeout(p.timer);p.reject(Error('Player closed'))}pending.clear()}};
}
let peerBridge=null,peerReady=false,peerSyncBusy=false,peerFrame=null;
const destroyBeforePeerTube=destroyVideo;destroyVideo=function(){peerReady=false;peerBridge?.destroy();peerBridge=null;peerFrame?.remove();peerFrame=null;destroyBeforePeerTube()};
const selectYouTubeClip=selectClip;selectClip=async function(i){const clip=clipItems[i];if(clip?.provider!=='peertube')return selectYouTubeClip(i);destroyVideo();activeClipIndex=i;const version=clipVersion;$('#videoPlaceholder')?.classList.add('hidden');$('#clipsStatus').textContent='Открываем видео PeerTube…';const frame=document.createElement('iframe');frame.id='peerTubeFrame';frame.title=clip.title;frame.src=clip.embedUrl+'?'+new URLSearchParams({api:'1',controls:'0',muted:'1',p2p:'0',title:'0',warningTitle:'0',peertubeLink:'0'});frame.allow='autoplay; fullscreen';frame.setAttribute('sandbox','allow-scripts allow-same-origin allow-presentation');$('.video-stage').prepend(frame);peerFrame=frame;const bridge=createPeerBridge(frame);peerBridge=bridge;$('#externalClip').href=clip.url;try{await bridge.ready;if(!focusOpen||version!==clipVersion||peerBridge!==bridge)return;await bridge.call('setVolume',0);await bridge.call('seek',Math.max(0,audio.currentTime+videoOffset));peerReady=true;$('#clipsStatus').textContent='PeerTube · видео следует за песней';syncVideo()}catch{if(!focusOpen||version!==clipVersion||activeClipIndex!==i)return;if(i+1<clipItems.length){selectClip(i+1);return}$('#videoPlaceholder')?.classList.remove('hidden');$('#clipsStatus').textContent='Видео недоступно. Можно открыть источник отдельно.'}};
async function syncPeerVideo(){if(!peerReady||!peerBridge||peerSyncBusy||!focusOpen)return;peerSyncBusy=true;const bridge=peerBridge;try{await bridge.call('setVolume',0);if(audio.paused||focusTab!=='clips')await bridge.call('pause');else if(!await bridge.call('isPlaying'))await bridge.call('play');const now=await bridge.call('getCurrentTime'),target=Math.max(0,audio.currentTime+videoOffset);if(Math.abs(Number(now)-target)>1.5&&Date.now()-lastVideoCorrection>2000){await bridge.call('seek',target);lastVideoCorrection=Date.now()}}catch{}finally{peerSyncBusy=false}}
const syncBeforePeerTube=syncVideo;syncVideo=function(){if(peerBridge)syncPeerVideo();else syncBeforePeerTube()};
